17	import { ErrorType } from '../../../basics/error-type';
18	import type { AsyncObject } from '../../../engine/reference-object/base-reference-object';
19	import { AsyncArrayObject } from '../../../engine/reference-object/base-reference-object';
20	import { type BaseValueObject, ErrorValueObject } from '../../../engine/value-object/base-value-object';
21	import type { LambdaValueObjectObject } from '../../../engine/value-object/lambda-value-object';
22	import { NumberValueObject } from '../../../engine/value-object/primitive-object';
23	import { BaseFunction } from '../../base-function';
24	
25	export class Makearray extends BaseFunction {
26	    override calculate(...variants: BaseValueObject[]) {
27	        if (variants.length !== 3) {
28	            return new ErrorValueObject(ErrorType.VALUE);
29	        }
30	
31	        const row = this.getIndexNumValue(variants[0]);
32	
33	        if (typeof row !== 'number') {
34	            return row;
35	        }
36	
37	        const column = this.getIndexNumValue(variants[1]);
38	
39	        if (typeof column !== 'number') {
40	            return column;
41	        }
42	
43	        if (!(variants[2].isValueObject() && (variants[2] as LambdaValueObjectObject).isLambda())) {
44	            return new ErrorValueObject(ErrorType.VALUE);
45	        }
46	
47	        const lambda = variants[2] as LambdaValueObjectObject;
48	
49	        const result: Array<Array<BaseValueObject | AsyncObject>> = [];
50	
51	        for (let r = 0; r < row; r++) {
52	            if (result[r] == null) {
53	                result[r] = [];
54	            }
55	            for (let c = 0; c < column; c++) {
56	                const value = lambda.execute(new NumberValueObject(r + 1), new NumberValueObject(c + 1));
57	
58	                result[r][c] = value;
59	            }
60	        }
61	
62	        return new AsyncArrayObject(result);
63	    }
64	
65	    override isAsync(): boolean {
66	        return true;
67	    }
68	}
