17	import type { Nullable } from '@univerjs/core';
18	import { Disposable } from '@univerjs/core';
19	
20	import { ErrorType } from '../basics/error-type';
21	import type { IFunctionNames } from '../basics/function';
22	import type { FunctionVariantType, NodeValueType } from '../engine/reference-object/base-reference-object';
23	import type { ArrayValueObject } from '../engine/value-object/array-value-object';
24	import { type BaseValueObject, ErrorValueObject } from '../engine/value-object/base-value-object';
25	import type { PrimitiveValueType } from '../engine/value-object/primitive-object';
26	
27	export class BaseFunction extends Disposable {
28	    private _unitId: Nullable<string>;
29	    private _subUnitId: Nullable<string>;
30	    private _row: number = -1;
31	    private _column: number = -1;
32	
33	    constructor(private _name: IFunctionNames) {
34	        super();
35	    }
36	
37	    get name() {
38	        return this._name;
39	    }
40	
41	    get unitId() {
42	        return this._unitId;
43	    }
44	
45	    get subUnitId() {
46	        return this._subUnitId;
47	    }
48	
49	    get row() {
50	        return this._row;
51	    }
52	
53	    get column() {
54	        return this._column;
55	    }
56	
57	    isAsync() {
58	        return false;
59	    }
60	
61	    isAddress() {
62	        return false;
63	    }
64	
65	    isCustom() {
66	        return false;
67	    }
68	
69	    setRefInfo(unitId: string, subUnitId: string, row: number, column: number) {
70	        this._unitId = unitId;
71	        this._subUnitId = subUnitId;
72	        this._row = row;
73	        this._column = column;
74	    }
75	
76	    calculateCustom(
77	        ...arg: Array<PrimitiveValueType | PrimitiveValueType[][]>
78	    ): PrimitiveValueType | PrimitiveValueType[][] {
79	        return null;
80	    }
81	
82	    calculate(...arg: BaseValueObject[]): NodeValueType {
83	        return new ErrorValueObject(ErrorType.VALUE);
84	    }
85	
86	    checkArrayType(variant: FunctionVariantType) {
87	        return variant.isReferenceObject() || (variant.isValueObject() && (variant as BaseValueObject).isArray());
88	    }
89	
90	    /**
91	     * Starting with 1
92	     * For instance, The column number (starting with 1 for the left-most column of table_array) that contains the return value.
93	     * https://support.microsoft.com/en-us/office/vlookup-function-0bbc8083-26fe-4963-8ab8-93a18ad188a1
94	     * @param indexNum
95	     * @returns
96	     */
97	    getIndexNumValue(indexNum: BaseValueObject) {
98	        if (indexNum.isArray()) {
99	            indexNum = (indexNum as ArrayValueObject).getFirstCell();
100	        }
101	
102	        if (indexNum.isBoolean()) {
103	            const colIndexNumV = indexNum.getValue() as boolean;
104	            if (colIndexNumV === false) {
105	                return new ErrorValueObject(ErrorType.VALUE);
106	            }
107	
108	            return 1;
109	        }
110	        if (indexNum.isString()) {
111	            const colIndexNumV = Number(indexNum.getValue() as string);
112	            if (isNaN(colIndexNumV)) {
113	                return new ErrorValueObject(ErrorType.REF);
114	            }
115	        } else if (indexNum.isNumber()) {
116	            const colIndexNumV = indexNum.getValue() as number;
117	            return colIndexNumV;
118	        }
119	
120	        return new ErrorValueObject(ErrorType.VALUE);
121	    }
122	
123	    /**
124	     * A logical value that specifies 1/TRUE , 0/FALSE, default 1
125	     * For instance range_lookup, A logical value that specifies whether you want VLOOKUP to find an approximate or an exact match
126	     * Approximate match - 1/TRUE
127	     * Exact match - 0/FALSE
128	     * https://support.microsoft.com/en-us/office/vlookup-function-0bbc8083-26fe-4963-8ab8-93a18ad188a1
129	     * For instance A1, A logical value that specifies what type of reference is contained in the cell ref_text.
130	     * If a1 is TRUE or omitted, ref_text is interpreted as an A1-style reference.
131	     * If a1 is FALSE, ref_text is interpreted as an R1C1-style reference.
132	     * https://support.microsoft.com/zh-cn/office/indirect-%E5%87%BD%E6%95%B0-474b3a3a-8a26-4f44-b491-92b6306fa261
133	     * @param logicValueObject
134	     * @returns
135	     */
136	    getZeroOrOneByOneDefault(logicValueObject?: BaseValueObject) {
137	        if (logicValueObject == null) {
138	            return 1;
139	        }
140	
141	        let logicValue = 1;
142	
143	        if (logicValueObject.isArray()) {
144	            logicValueObject = (logicValueObject as ArrayValueObject).getFirstCell();
145	        }
146	
147	        if (logicValueObject.isBoolean()) {
148	            const logicV = logicValueObject.getValue() as boolean;
149	            if (logicV === false) {
150	                logicValue = 0;
151	            }
152	        } else if (logicValueObject.isString()) {
153	            return;
154	        } else if (logicValueObject.isNumber()) {
155	            const logicV = logicValueObject.getValue() as number;
156	            if (logicV === 0) {
157	                logicValue = 0;
158	            }
159	        }
160	
161	        return logicValue;
162	    }
