23	export class And extends BaseFunction {
24	    override calculate(...logicalValues: BaseValueObject[]) {
25	        if (logicalValues.length === 0) {
26	            return new ErrorValueObject(ErrorType.NA);
27	        }
28	
29	        let result = true;
30	        let noBoolean = true;
31	        let errorValue = null;
32	
33	        for (const logicalValue of logicalValues) {
34	            if (logicalValue.isError()) {
35	                return logicalValue;
36	            }
37	
38	            if (logicalValue.isArray()) {
39	                (logicalValue as ArrayValueObject).iterator((value) => {
40	                    if (value?.isError()) {
41	                        errorValue = value;
42	                        return false;
43	                    } else if (value?.isBoolean() || value?.isNumber()) {
44	                        result = result && !!value.getValue();
45	                        noBoolean = false;
46	                    }
47	                });
48	
49	                if (errorValue) {
50	                    return errorValue;
51	                }
52	            } else if (logicalValue.isBoolean() || logicalValue.isNumber()) {
53	                result = result && !!logicalValue.getValue();
54	                noBoolean = false;
55	            }
56	        }
57	
58	        return noBoolean ? new ErrorValueObject(ErrorType.VALUE) : new BooleanValueObject(result);
