17	import { ErrorType } from '../../../basics/error-type';
18	import { expandArrayValueObject } from '../../../engine/utils/array-object';
19	import type { ArrayValueObject } from '../../../engine/value-object/array-value-object';
20	import { type BaseValueObject, ErrorValueObject } from '../../../engine/value-object/base-value-object';
21	import { BooleanValueObject } from '../../../engine/value-object/primitive-object';
22	import { BaseFunction } from '../../base-function';
23	
24	export class If extends BaseFunction {
25	    override calculate(logicalTest: BaseValueObject, valueIfTrue: BaseValueObject, valueIfFalse: BaseValueObject = new BooleanValueObject(false)) {
26	        if (logicalTest.isError() || valueIfTrue.isError()) {
27	            return new ErrorValueObject(ErrorType.NA);
28	        }
29	
30	        // get single value object
31	        logicalTest = this._getSingleValueObject(logicalTest);
32	
33	        if (!logicalTest.isArray()) {
34	            return logicalTest.getValue() ? valueIfTrue : valueIfFalse;
35	        }
36	
37	        // get max row length
38	        const maxRowLength = Math.max(
39	            logicalTest.isArray() ? (logicalTest as ArrayValueObject).getRowCount() : 1,
40	            valueIfTrue.isArray() ? (valueIfTrue as ArrayValueObject).getRowCount() : 1,
41	            valueIfFalse.isArray() ? (valueIfFalse as ArrayValueObject).getRowCount() : 1
42	        );
43	
44	        // get max column length
45	        const maxColumnLength = Math.max(
46	            logicalTest.isArray() ? (logicalTest as ArrayValueObject).getColumnCount() : 1,
47	            valueIfTrue.isArray() ? (valueIfTrue as ArrayValueObject).getColumnCount() : 1,
48	            valueIfFalse.isArray() ? (valueIfFalse as ArrayValueObject).getColumnCount() : 1
49	        );
50	
51	        const logicalTestArray = expandArrayValueObject(maxRowLength, maxColumnLength, logicalTest);
52	        const valueIfTrueArray = expandArrayValueObject(maxRowLength, maxColumnLength, valueIfTrue, new ErrorValueObject(ErrorType.NA));
53	        const valueIfFalseArray = expandArrayValueObject(maxRowLength, maxColumnLength, valueIfFalse, new ErrorValueObject(ErrorType.NA));
54	
55	        return logicalTestArray.map((logicalTestValue, rowIndex, columnIndex) => {
56	            if (logicalTestValue.isNull()) {
57	                return new ErrorValueObject(ErrorType.NA);
58	            } else {
59	                const valueIfTrueValue = valueIfTrueArray.get(rowIndex, columnIndex);
60	                const valueIfFalseValue = valueIfFalseArray.get(rowIndex, columnIndex);
61	
62	                return this._calculateSingleCell(logicalTestValue, valueIfTrueValue, valueIfFalseValue);
63	            }
64	        });
65	    }
66	
67	    private _getSingleValueObject(valueObject: BaseValueObject) {
68	        if (valueObject.isArray() && (valueObject as ArrayValueObject).getRowCount() === 1 && (valueObject as ArrayValueObject).getColumnCount() === 1) {
69	            return (valueObject as ArrayValueObject).getFirstCell();
70	        }
71	        return valueObject;
72	    }
73	
74	    private _calculateSingleCell(logicalTest: BaseValueObject, valueIfTrue: BaseValueObject, valueIfFalse: BaseValueObject) {
75	        if (logicalTest.isNull()) {
76	            return new ErrorValueObject(ErrorType.NA);
77	        }
78	
79	        const logicalTestValue = logicalTest.getValue();
80	
81	        // true or non-zero
82	        if (logicalTestValue) {
83	            if (valueIfTrue.isNull()) {
84	                return new ErrorValueObject(ErrorType.NA);
85	            }
86	
87	            return valueIfTrue;
88	        }
89	
90	        if (valueIfFalse.isNull()) {
91	            return new ErrorValueObject(ErrorType.NA);
92	        }
93	
94	        return valueIfFalse;
95	    }
96	}
